CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,is_admin TINYINT(1) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE anime (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,mal_id INT UNSIGNED NULL UNIQUE,anilist_id INT UNSIGNED NULL UNIQUE,title VARCHAR(255) NOT NULL,english_title VARCHAR(255),japanese_title VARCHAR(255),synopsis TEXT,poster TEXT,banner TEXT,trailer_url TEXT,type VARCHAR(30),status VARCHAR(60),episodes INT,duration VARCHAR(60),score DECIMAL(4,2),rank INT,popularity INT,members INT,favorites INT,year SMALLINT,season VARCHAR(20),source VARCHAR(80),studio VARCHAR(160),aired_from DATE, aired_to DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(title),INDEX(type),INDEX(year),INDEX(popularity)) ENGINE=InnoDB;
CREATE TABLE genres(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);CREATE TABLE anime_genres(anime_id INT UNSIGNED,genre_id INT UNSIGNED,PRIMARY KEY(anime_id,genre_id),FOREIGN KEY(anime_id) REFERENCES anime(id) ON DELETE CASCADE,FOREIGN KEY(genre_id) REFERENCES genres(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE characters(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,mal_id INT UNSIGNED UNIQUE,name VARCHAR(180) NOT NULL,image TEXT);CREATE TABLE anime_characters(anime_id INT UNSIGNED,character_id INT UNSIGNED,PRIMARY KEY(anime_id,character_id),FOREIGN KEY(anime_id) REFERENCES anime(id) ON DELETE CASCADE,FOREIGN KEY(character_id) REFERENCES characters(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE seasons(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80),year SMALLINT);CREATE TABLE episodes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,anime_id INT UNSIGNED NOT NULL,number INT NOT NULL,title VARCHAR(255),air_date DATE,UNIQUE(anime_id,number),FOREIGN KEY(anime_id) REFERENCES anime(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE video_sources(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,anime_id INT UNSIGNED NOT NULL,episode_id INT UNSIGNED NOT NULL,language VARCHAR(50) NOT NULL,source_type ENUM('mp4','hls','iframe') NOT NULL,source_url TEXT NOT NULL,server_name VARCHAR(100) NOT NULL,priority INT DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(anime_id) REFERENCES anime(id) ON DELETE CASCADE,FOREIGN KEY(episode_id) REFERENCES episodes(id) ON DELETE CASCADE,INDEX(anime_id,episode_id,active)) ENGINE=InnoDB;
CREATE TABLE anime_languages(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,anime_id INT UNSIGNED NOT NULL,language VARCHAR(50) NOT NULL,UNIQUE(anime_id,language),FOREIGN KEY(anime_id) REFERENCES anime(id) ON DELETE CASCADE);CREATE TABLE watch_history(user_id INT UNSIGNED,anime_id INT UNSIGNED,episode_number INT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,anime_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(anime_id) REFERENCES anime(id) ON DELETE CASCADE) ENGINE=InnoDB;CREATE TABLE watchlist(user_id INT UNSIGNED,anime_id INT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,anime_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(anime_id) REFERENCES anime(id) ON DELETE CASCADE) ENGINE=InnoDB;CREATE TABLE ratings(user_id INT UNSIGNED,anime_id INT UNSIGNED,rating TINYINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,anime_id));CREATE TABLE settings(`key` VARCHAR(80) PRIMARY KEY,value TEXT);CREATE TABLE sync_logs(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,finished_at TIMESTAMP NULL,status VARCHAR(30),message TEXT);
